create unique index if not exists schoolpro_result_approval_result_unique on public.schoolpro_result_approvals(result_id);
create or replace function public.review_schoolpro_result(p_result uuid,p_status text,p_notes text default null) returns void language plpgsql security definer set search_path='' as $$declare r public.schoolpro_results;begin select * into r from public.schoolpro_results where id=p_result for update;if r.id is null then raise exception 'Result not found';end if;if p_status not in('approved','rejected') then raise exception 'Invalid review status';end if;if not(public.schoolpro_member_can_manage(r.school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=r.school_id and m.user_id=auth.uid() and m.role::text in('exam_officer','head_teacher','vice_principal'))) then raise exception 'Not authorized';end if;insert into public.schoolpro_result_approvals(school_id,result_id,status,reviewed_by,reviewed_at,notes) values(r.school_id,r.id,p_status,auth.uid(),now(),p_notes) on conflict(result_id) do update set status=excluded.status,reviewed_by=excluded.reviewed_by,reviewed_at=excluded.reviewed_at,notes=excluded.notes;update public.schoolpro_results set status=case when p_status='approved' then 'approved'::public.schoolpro_result_status else 'draft'::public.schoolpro_result_status end,approved_by=case when p_status='approved' then auth.uid() else null end,approved_at=case when p_status='approved' then now() else null end,published_at=null where id=r.id;end$$;
revoke all on function public.review_schoolpro_result(uuid,text,text) from public;grant execute on function public.review_schoolpro_result(uuid,text,text) to authenticated;
create or replace function public.ensure_schoolpro_default_assessment_scheme(p_school uuid) returns uuid language plpgsql security definer set search_path='' as $$declare sid uuid;begin if not public.schoolpro_member_can_manage(p_school) then raise exception 'Not authorized';end if;select id into sid from public.schoolpro_assessment_schemes where school_id=p_school and is_default=true limit 1;if sid is null then insert into public.schoolpro_assessment_schemes(school_id,name,school_level,components,is_default) values(p_school,'Standard 40/60','All',jsonb_build_array(jsonb_build_object('key','ca1_assignment','label','1st CA Assignment','max',10),jsonb_build_object('key','ca2_assignment','label','2nd CA Assignment','max',10),jsonb_build_object('key','ca1_test','label','1st CA Test','max',10),jsonb_build_object('key','ca2_test','label','2nd CA Test','max',10),jsonb_build_object('key','exam','label','Exam','max',60)),true) returning id into sid;end if;return sid;end$$;
revoke all on function public.ensure_schoolpro_default_assessment_scheme(uuid) from public;grant execute on function public.ensure_schoolpro_default_assessment_scheme(uuid) to authenticated;